package com.danawa.io;

public class BytesBuffer {

	/** The contents of the BytesRef. Should never be {@code null}. */
	public byte[] bytes;

	/** Offset of first valid byte. */
	public int offset;

	/** limit of used bytes. */
	public int limit;

	public BytesBuffer() { }

	public BytesBuffer(int size) {
		this.bytes = new byte[size];
		clear();
	}

	public BytesBuffer(byte[] buffer) {
		this.bytes = buffer;
		clear();
	}

	public BytesBuffer(byte[] buffer, int limit) {
		this.bytes = buffer;
		this.limit = limit;
	}

	public BytesBuffer(byte[] buffer, int offset, int limit) {
		this.bytes = buffer;
		this.offset = offset;
		this.limit = limit;
	}

	public void init(byte[] buffer, int offset, int limit) {
		this.bytes = buffer;
		this.offset = offset;
		this.limit = limit;
	}

	public void clear() {
		offset = 0;
		limit = bytes.length;
	}

	public int size() {
		return bytes.length;
	}

	public BytesBuffer flip() {
		limit = offset;
		offset = 0;
		return this;
	}

	// 현재위치로부터 offset만큼 떨어진 위치의 byte를 리턴해준다.
	// read하지 않고 값을 확인하고 싶을때 사용.
	// 2012-5-5 array[pos+offset] & 0xFF는 음수 byte를 양의 int로 바꾸어 주므로 올바른 값을 리턴할수 없다.
	// byte데이터 그대로를 리턴하도록 한다.
	public byte get(int i) {
		return bytes[offset + i];
	}

	public byte[] array() {
		return bytes;
	}

	public int pos() {
		return offset;
	}

	public int limit() {
		return limit;
	}

	public void pos(int pos) {
		this.offset = pos;
	}

	public void skip(int n) {
		this.offset += n;
	}

	public void limit(int limit) {
		this.limit = limit;
	}

	public int length() {
		return limit - offset;
	}

	public int remaining() {
		return limit - offset;
	}

	public byte readByte() {
		return bytes[offset++];
	}

	public int read() {
		return (bytes[offset++] & 0xFF);
	}

	public void write(int b) {
		bytes[offset++] = (byte) b;
	}

	public void write(byte[] src, int srcPos, int srcLen) {
		System.arraycopy(src, srcPos, bytes, offset, srcLen);
		offset += srcLen;
	}

	public static int compareBuffer(BytesBuffer buf1, BytesBuffer buf2) {
		int len1 = buf1.length();
		int len2 = buf2.length();
		int len = len1 < len2 ? len1 : len2;
		for (int i = 0; i < len; i++) {
			if (buf1.get(i) != buf2.get(i)) {
				return buf1.get(i) - buf2.get(i);
			}
		}
		return len1 - len2;
	}

	public String toString() {
		StringBuilder sb = new StringBuilder();
		for (int i = offset; i < limit; i++) {
			sb.append(bytes[i]);
