   112→				CharVector key = CharVector.valueOf(list.get(j));
   113→				CharSequence[] value = new CharSequence[list.size() - 1];
   114→				int idx = 0;
   115→				for (int k = 0; k < list.size(); k++) {
   116→					CharSequence val = list.get(k);
   117→					if (!key.equals(val)) {
   118→						// 다른것만 value로 넣는다.
   119→						value[idx++] = val;
   120→					}
   121→				}
