   833→	public static void expansionKeyword(String text, TokenStream stream, JSONWriter writer) {
   834→		CharTermAttribute termAttr = stream.addAttribute(CharTermAttribute.class);
   835→		TypeAttribute typeAttr = stream.addAttribute(TypeAttribute.class);
   836→		ExtraTermAttribute extAttr = stream.addAttribute(ExtraTermAttribute.class);
   837→		SynonymAttribute synAttr = stream.addAttribute(SynonymAttribute.class);
   838→		OffsetAttribute offAttr = stream.addAttribute(OffsetAttribute.class);
   839→
   840→		List<Object> termWords;
   841→		// 검색어 확장을 위한 변수
   842→		List<Object> extraTermWords;
   843→		ProductNameDictionary dictionary = getDictionary();
   844→		SynonymDictionary synonymDict = dictionary.getDictionary(ProductNameDictionary.DICT_SYNONYM, SynonymDictionary.class);
   845→
   846→		List<CharSequence> synonyms;
   847→
   848→		List<String> tempTermList = new ArrayList<>();
   849→		Map<String, Object> hash = new LinkedHashMap<>();
   850→		// 풀텀, 합성텀에 대해 결과를 저장하는 변수
   851→		Map<String, Object> combineTermSynonym = new HashMap<>();
   852→		// 확장어에 대해 결과를 저장하는 변수
   853→		Map<String, Object> extensionSynonym = null;
   854→
   855→		int[] offset = {0, 0};
   856→		int[] offsetPrev = {0, 0};
   857→
   858→		try {
   859→			stream.reset();
   860→			while (stream.incrementToken()) {
   861→				offsetPrev = new int[]{offset[0], offset[1]};
   862→				String term = String.valueOf(termAttr);
   863→				termWords = new ArrayList<>();
   864→				extraTermWords = new ArrayList<>();
   865→				String type = typeAttr.type();
   866→				offset = new int[]{offAttr.startOffset(), offAttr.endOffset()};
   867→				logger.trace("TERM:{} / {}", term, type);
   868→				//풀텀일 경우는 펄텀유사어 따로 처리
   869→				if (type.equals(ProductNameTokenizer.FULL_STRING)) {
   870→					if ((synonyms = synAttr.getSynonyms()) != null && synonyms.size() > 0) {
   871→
   872→						termWords = new ArrayList<>();
   873→						ArrayList<Object> termList = divideTerm(text);
   874→						termWords.add(termList);
   875→
   876→						logger.trace("FULLTERM SYNONYM {} / {} ", term, synonyms);
   877→
   878→						for (CharSequence synonym : synonyms) {
   879→							String s = String.valueOf(synonym);
   880→
   881→							String[] synonymList = s.split(" ");
   882→
   883→							if(synonymList.length > 1){
   884→								termWords.add(synonymList);
   885→							}else{
   886→								termWords.add(s);
   887→							}
   888→						}
   889→						combineTermSynonym.put(term, termWords);
   890→					}
