   908→    private static void combineNextNextEntry(List<RuleEntry> tmpList, RuleEntry nextEntry, RuleEntry nextNextEntry, String type) {
   909→        if (nextNextEntry != null && nextEntry.length == 1 && nextNextEntry.length == 1 && ((nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start])) && nextNextEntry.type == NUMBER || nextEntry.type == NUMBER && (nextNextEntry.type == ALPHA || nextNextEntry.type == UNIT && Character.isAlphabetic(nextNextEntry.buf[nextNextEntry.start])))) {
   910→            tmpList.add(mergeNewEntry(nextEntry, nextNextEntry, type));
   911→        }
   912→    }
   913→
   914→    private static void combineNextNextEntry(List<RuleEntry> tmpList, RuleEntry currentEntry, RuleEntry nextEntry, RuleEntry nextNextEntry, String type) {
   915→        if (nextNextEntry != null && nextEntry.length == 1 && nextNextEntry.length == 1 && ((nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start])) && nextNextEntry.type == NUMBER || nextEntry.type == NUMBER && (nextNextEntry.type == ALPHA || nextNextEntry.type == UNIT && Character.isAlphabetic(nextNextEntry.buf[nextNextEntry.start])))) {
   916→            tmpList.add(mergeNewEntry(nextEntry, nextNextEntry, type));
   917→            tmpList.add(mergeNewEntry(currentEntry, nextEntry, nextNextEntry, type));
   918→        }
   919→    }
   920→
   921→    private static void combineNextEntry(List<RuleEntry> tmpList, RuleEntry currentEntry, RuleEntry nextEntry, String type) {
   922→        if (nextEntry != null && nextEntry.length == 1 && ((nextEntry.type == ALPHA || currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start])) || nextEntry.type == NUMBER)) {
   923→            if ((currentEntry.type == NUMBER && (nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start]))) || ((currentEntry.type == ALPHA || (currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start]))) && nextEntry.type == NUMBER)) {
   924→                tmpList.add(mergeNewEntry(currentEntry, nextEntry, type));
   925→            }
   926→        }
   927→    }
   928→
   929→    private static void combineNextUnitEntry(List<RuleEntry> tmpList, RuleEntry currentEntry, RuleEntry nextEntry, String type) {
   930→        if (nextEntry != null && currentEntry.type == NUMBER && nextEntry.type == UNIT) {
   931→            tmpList.add(mergeNewEntry(currentEntry, nextEntry, type));
   932→        }
   933→    }
