   245→	static class SearchResultIterator extends AbstractSearchResultIterator {
   246→		private SearchHit[] hits;
   247→		private int rowNum;
   248→		private int hitsInx;
   249→		private Map<String, Object> rowData;
   250→		private TimeValue timeOut;
   251→		private DataModifier dataModifier;
