   255→		@Override 
   256→		public Iterator<Map<String, Object>> doSearch(Client client, String index, QueryBuilder query, List<SortBuilder<?>> sortSet, HighlightBuilder highlight, DataModifier dataModifier, int from, int size) {
   257→			/**
   258→			 * 단순 검색. 빠르지만 1만건 이상 검색결과 검색 불가능
   259→			 **/
   260→			try {
   261→				SearchSourceBuilder source = new SearchSourceBuilder();
   262→				if (sortSet != null) {
   263→					for (SortBuilder<?> sort : sortSet) {
   264→						source.sort(sort);
   265→					}
   266→				}
   267→				// if (highlight != null) {
   268→				// 	source.highlighter(highlight);
   269→				// }
   270→				this.dataModifier = dataModifier;
   271→				source.query(query);
   272→				SearchRequest search = new SearchRequest(index.split("[,]"));
   273→				source.from(from);
   274→				source.size(size);
   275→				source.timeout(timeOut);
   276→				search.source(source);
   277→				SearchResponse response = client.search(search).get();
   278→				hits = response.getHits().getHits();
   279→				rowNum = from;
   280→				rowData = null;
   281→				return this;
   282→			} catch (Exception e) {
   283→				logger.debug("SEARCH ERROR : {} ( It may be over 10,000 records ) ", e.getMessage());
   284→			}
   285→			return null;
   286→		}
