   288→		@Override public boolean hasNext() {
   289→			boolean ret = false;
   290→			if (rowData != null) { return true; }
   291→			try {
   292→				for (; hits != null && hits.length > 0;) {
   293→					for (; hitsInx < hits.length;) {
   294→						rowData = processHit(hits[hitsInx], rowNum, dataModifier);
   295→						hitsInx++;
   296→						rowNum++;
   297→						break;
   298→					}
   299→
   300→					if (rowData != null) {
   301→						ret = true;
   302→						break;
   303→					} else {
   304→						ret = false;
   305→						break;
   306→					}
   307→				}
   308→			} catch (Exception e) {
   309→				logger.error("", e);
   310→			}
   311→			return ret;
   312→		}
