   323→	static class ScrollSearchResultIterator extends AbstractSearchResultIterator {
   324→
   325→		private Client client;
   326→		private SearchHit[] hits;
   327→		private ClearScrollRequest clearScroll;
   328→		private String scrollId;
   329→		private int rowNum;
   330→		private int hitsInx;
   331→		private Map<String, Object> rowData;
   332→		private TimeValue scrollKeepAlive;
   333→		private TimeValue timeOut;
   334→		private DataModifier dataModifier;
   335→		private int scrollSize;
   336→		private int size;
   337→
   338→		public ScrollSearchResultIterator() {
   339→			this(DEFAULT_SEARCH_TIME_OUT, DEFAULT_SCROLL_KEEP_ALIVE, DEFAULT_SCROLL_SIZE);
   340→		}
   341→
   342→		public ScrollSearchResultIterator(TimeValue timeOut, TimeValue scrollKeepAlive, int scrollSize) {
   343→			this.scrollKeepAlive = scrollKeepAlive;
   344→			this.timeOut = timeOut;
   345→			this.scrollSize = scrollSize;
   346→		}
   347→
   348→		@Override
   349→		public Iterator<Map<String, Object>> doSearch(Client client, String index, QueryBuilder query, List<SortBuilder<?>> sortSet, HighlightBuilder highlight, DataModifier dataModifier, int from, int size) {
   350→			/**
   351→			 * 스크롤 스트리밍 검색. 느리지만 1만건 이상 검색결과를 추출가능함.
   352→			 **/
   353→			try {
   354→				this.client = client;
   355→				SearchSourceBuilder source = new SearchSourceBuilder();
   356→				if (sortSet != null) {
   357→					for (SortBuilder<?> sort : sortSet) {
   358→						source.sort(sort);
   359→					}
   360→				}
   361→				// if (highlight != null) {
   362→				// 	source.highlighter(highlight);
   363→				// }
   364→				this.dataModifier = dataModifier;
   365→				source.query(query);
   366→				SearchRequest search = new SearchRequest(index.split("[,]"));
   367→				clearScroll = new ClearScrollRequest();
   368→				source.from(0);
   369→				source.size(scrollSize);
   370→				source.timeout(timeOut);
   371→				search.source(source);
   372→				search.scroll(scrollKeepAlive);
   373→				SearchResponse response = client.search(search).get();
   374→				hits = response.getHits().getHits();
   375→				scrollId = response.getScrollId();
   376→				clearScroll.addScrollId(scrollId);
   377→				for (rowNum = 0; hits != null && hits.length > 0 && rowNum < from;) {
   378→					if (rowNum + hits.length <= from) {
   379→						rowNum += hits.length;
   380→					} else {
   381→						hitsInx = from - rowNum;
   382→						rowNum = from;
   383→						break;
   384→					}
   385→					SearchScrollRequest scrollRequest = new SearchScrollRequest(scrollId);
   386→					scrollRequest.scroll(scrollKeepAlive);
   387→					response = client.searchScroll(scrollRequest).get();
   388→					hits = response.getHits().getHits();
   389→					scrollId = response.getScrollId();
   390→					clearScroll.addScrollId(scrollId);
   391→				}
   392→				this.size = size;
   393→				rowData = null;
   394→				return this;
   395→			} catch (Exception e) {
   396→				logger.error("", e);
   397→			}
   398→			return null;
   399→		}
   400→
   401→		@Override public boolean hasNext() {
   402→			boolean ret = false;
   403→			if (rowData != null) { return true; }
   404→			try {
   405→				for (; hits != null && hits.length > 0 && (size == -1 || size > 0);) {
   406→					for (; hitsInx < hits.length && (size == -1 || size > 0);) {
   407→						rowData = processHit(hits[hitsInx], rowNum, dataModifier);
   408→						hitsInx++;
   409→						rowNum++;
   410→						if (size != -1) {
   411→							size--;
   412→						}
   413→						break;
   414→					}
   415→
   416→					if (rowData != null) {
   417→						ret = true;
   418→						break;
   419→					}
   420→
   421→					SearchScrollRequest scrollRequest = new SearchScrollRequest(scrollId);
   422→					scrollRequest.scroll(scrollKeepAlive);
   423→
   424→					SearchResponse response = client.searchScroll(scrollRequest).get();
   425→					hits = response.getHits().getHits();
   426→					scrollId = response.getScrollId();
   427→					clearScroll.addScrollId(scrollId);
   428→					hitsInx = 0;
   429→				}
   430→				if (size == 0 || (hits == null && rowData == null)) {
   431→					close(); 
   432→					ret = false;
   433→				}
   434→			} catch (Exception e) {
   435→				logger.error("", e);
   436→			}
   437→			return ret;
   438→		}
   439→
   440→		@Override public Map<String, Object> next() {
   441→			Map<String, Object> ret = rowData;
   442→			rowData = null;
   443→			return ret;
   444→		}
   445→
   446→		public void close() {
   447→			try {
   448→				client.clearScroll(clearScroll).get();
   449→			} catch (Exception ignore) { }
   450→		}
   451→	}
   452→}

