package com.danawa.search.util;

import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import org.elasticsearch.action.ActionFuture;
import org.elasticsearch.action.search.*;
import org.elasticsearch.action.support.PlainActionFuture;
import org.elasticsearch.common.settings.Settings;
import org.elasticsearch.core.TimeValue;
import org.elasticsearch.index.query.MatchQueryBuilder;
import org.elasticsearch.threadpool.ThreadPool;
import org.json.JSONObject;

import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

/**
 * ES 9.x 호환 원격 HTTP 클라이언트
 * NodeClient 상속 대신 독립적인 HTTP 기반 검색 클라이언트로 구현
 */
public class RemoteNodeClient {
    private static final Logger logger = LogManager.getLogger(RemoteNodeClient.class);
    private String index;
    private String host;
    private int port;
    private String username;
    private String password;
    private String url;
    private Settings settings;
    private ThreadPool threadPool;

    public RemoteNodeClient(Settings settings, ThreadPool threadPool, String index, String host, int port) {
        this.settings = settings;
        this.threadPool = threadPool;
        this.host = host;
        this.port = port;
        this.url = String.format("http://%s:%d", this.host, this.port);
        this.index = index;
    }

    public RemoteNodeClient(Settings settings, ThreadPool threadPool, String index, String host, int port, String username, String password) {
        this(settings, threadPool, index, host, port);
        this.username = username;
        this.password = password;
    }

    /**
     * 원격 검색 수행 - JSON 응답 반환
     */
    public JSONObject search(SearchRequest request) {
        HttpURLConnection co = null;
        BufferedReader reader = null;
