   235→
   236→	/**
   237→	 * 상품검색용 분석질의 객체 생성기, 분석기 속성 (동의어, 확장어 등) 을 고려한 질의 JSON문자열을 생성한다.
   238→	 */
   239→	public static JSONObject buildAnalyzedJSONQuery(TokenStream stream, String[] fields, String totalIndex, String analyzer) {
   240→		JSONObject ret = new JSONObject();
   241→		CharTermAttribute termAttr = stream.addAttribute(CharTermAttribute.class);
   242→		TypeAttribute typeAttr = stream.addAttribute(TypeAttribute.class);
   243→		SynonymAttribute synAttr = stream.addAttribute(SynonymAttribute.class);
   244→		ExtraTermAttribute extAttr = stream.addAttribute(ExtraTermAttribute.class);
   245→		try {
   246→			stream.reset();
   247→			JSONObject mainQuery = new JSONObject();
   248→			ret = mainQuery;
   249→			while (stream.incrementToken()) {
   250→				String term = String.valueOf(termAttr);
   251→				String type = typeAttr.type();
   252→				logger.trace("TOKEN:{} / {}", term, type);
   253→
   254→				List<CharSequence> synonyms = null;
   255→				JSONObject termQuery = new JSONObject();
   256→				termQuery.put(MULTIMATCH, 
   257→					new JSONObject().put(ANALYZER, analyzer)
   258→						.put(QUERY, term)
   259→						.put(FIELDS, fields)
   260→					);
   261→
   262→				if (synAttr != null && (synonyms = synAttr.getSynonyms()) != null && synonyms.size() > 0) {
   263→					logger.trace("SYNONYM [{}] = {}", term, synonyms);
   264→					termQuery = synonymJSONQuery(termQuery, synonyms, fields, termAttr, typeAttr, synAttr, extAttr, analyzer);
   265→				}
   266→				if (extAttr != null && extAttr.size() > 0) {
   267→					logger.trace("EXTRA [{}] = {}", term, extAttr);
   268→					termQuery = extraJSONQuery(termQuery, fields, termAttr, typeAttr, synAttr, extAttr, analyzer);
   269→				}
   270→
   271→				if (!ProductNameTokenizer.FULL_STRING.equals(type)) {
   272→					appendJSONQuery(mainQuery, MUST, termQuery);
   273→				}
   274→
   275→			}
   276→		} catch (Exception e) {
   277→			logger.error("", e);
   278→		} finally {
   279→			try { stream.close(); } catch (Exception ignore) { }
   280→		}
   281→		return ret;
   282→	}
   283→
   284→	private static void appendJSONQuery(JSONObject mainQuery, String mode, JSONObject termQuery) {
   285→		JSONObject boolQuery = null;
   286→		if (mainQuery.has(BOOL)) {
   287→			boolQuery = mainQuery.getJSONObject(BOOL);
   288→		} else {
   289→			boolQuery = new JSONObject();
   290→			mainQuery.put(BOOL, boolQuery);
   291→		}
   292→		JSONArray termQueries = null;
   293→		if (boolQuery.has(mode)) {
   294→			termQueries = boolQuery.getJSONArray(mode);
   295→		} else {
   296→			termQueries = new JSONArray();
   297→			boolQuery.put(mode, termQueries);
   298→		}
   299→		termQueries.put(termQuery);
   300→	}
   301→
   302→	/**
   303→	 * 전체 문장검색 질의객체 생성
   304→	 */
   305→	public final static QueryBuilder fullTermQuery(String totalIndex, Map<String, Float> boostMap, String phrase, int slop) {
   306→		BoolQueryBuilder ret = QueryBuilders.boolQuery();
   307→		ret.should().add(QueryBuilders.matchPhraseQuery(totalIndex, phrase).boost(0).slop(slop).analyzer(WHITESPACE));
   308→		return ret;
   309→	}
   310→
   311→	/**
   312→	 * 문장검색 질의객체 생성
   313→	 */
   314→	public final static QueryBuilder phraseQuery(String[] fields, Map<String, Float> boostMap, String phrase, int slop, String analyzer) {
   315→		BoolQueryBuilder ret = QueryBuilders.boolQuery();
   316→		String[] split = phrase.split(" ");
   317→		for (String word : split) {
   318→			ret.must().add(QueryBuilders.multiMatchQuery(word, fields).fields(boostMap).analyzer(analyzer));
   319→		}
   320→		return ret;
   321→	}
   322→
   323→	/**
   324→	 * 문장검색 질의객체 생성
   325→	 */
   326→	public final static JSONObject phraseJSONQuery(String[] fields, String phrase, int slop, String analyzer) {
   327→		JSONObject ret = new JSONObject();
   328→		String[] split = phrase.split(" ");
   329→		for (String word : split) {
   330→			JSONObject termQuery = new JSONObject();
   331→			termQuery.put(MULTIMATCH, 
   332→				new JSONObject().put(ANALYZER, analyzer)
   333→					.put(QUERY, word)
   334→					.put(FIELDS, fields)
   335→				);
   336→			appendJSONQuery(ret, MUST, termQuery);
   337→		}
   338→		return ret;
   339→	}
   340→
   341→	/**
   342→	 * 동의어 질의객체 생성
   343→	 */
   344→	public final static QueryBuilder synonymQuery(QueryBuilder query, List<CharSequence> synonyms, String[] fields, Map<String, Float> boostMap, 
   345→		CharTermAttribute termAttr, TypeAttribute typeAttr, SynonymAttribute synAttr, 
   346→		ExtraTermAttribute extAttr, List<String> highlightTerms, JSONArray explain, String analyzer) {
   347→		QueryBuilder ret = query;
   348→		BoolQueryBuilder subQuery = QueryBuilders.boolQuery();
   349→		subQuery.should().add(query);
   350→		for (int sinx = 0; sinx < synonyms.size(); sinx++) {
   351→			String synonym = String.valueOf(synonyms.get(sinx));
   352→			if (explain != null) {
   353→				explain.put(synonym);
   354→			}
   355→			if (synonym.indexOf(" ") == -1) {
   356→				subQuery.should().add(QueryBuilders.multiMatchQuery(synonym, fields).fields(boostMap).analyzer(analyzer));
   357→			} else {
   358→				/**
   359→				 * 공백이 포함된 단어는 문장검색으로 질의
   360→				 */
   361→				subQuery.should().add(phraseQuery(fields, boostMap, synonym, 3, analyzer));
   362→			}
   363→		}
   364→		ret = subQuery;
   365→		return ret;
   366→	}
   367→
   368→	/**
   369→	 * 동의어 JSON질의 문자열을 생성한다.
   370→	 */
   371→	public final static JSONObject synonymJSONQuery(JSONObject query, List<CharSequence> synonyms, String[] fields,
   372→		CharTermAttribute termAttr, TypeAttribute typeAttr, SynonymAttribute synAttr, 
   373→		ExtraTermAttribute extAttr, String analyzer) {
   374→		JSONObject ret = query;
   375→		JSONObject subQuery = new JSONObject();
   376→		appendJSONQuery(subQuery, SHOULD, query);
   377→		for (int sinx = 0; sinx < synonyms.size(); sinx++) {
   378→			String synonym = String.valueOf(synonyms.get(sinx));
   379→			if (synonym.indexOf(" ") == -1) {
   380→				JSONObject termQuery = new JSONObject();
   381→				termQuery.put(MULTIMATCH, 
   382→					new JSONObject().put(ANALYZER, analyzer)
   383→						.put(QUERY, synonym)
   384→						.put(FIELDS, fields)
   385→					);
   386→				appendJSONQuery(subQuery, SHOULD, termQuery);
   387→			} else {
   388→				/**
   389→				 * 공백이 포함된 단어는 문장검색으로 질의
   390→				 */
   391→				appendJSONQuery(subQuery, SHOULD, phraseJSONQuery(fields, synonym, 3, analyzer));
   392→			}
   393→		}
   394→		ret = subQuery;
   395→		return ret;
   396→	}
   397→
   398→	/**
   399→	 * 확장어 질의객체 생성
   400→	 */
   401→	public final static QueryBuilder extraQuery(QueryBuilder query, String[] fields, Map<String, Float> boostMap, 
   402→		CharTermAttribute termAttr, TypeAttribute typeAttr, SynonymAttribute synAttr, 
   403→		ExtraTermAttribute extAttr, List<String> highlightTerms, JSONArray explain, String analyzer) {
   404→		List<CharSequence> synonyms = null;
   405→		QueryBuilder ret = query;
   406→		if (extAttr != null && extAttr.size() > 0) {
   407→			JSONArray termExplain = null;
   408→			if (explain != null) {
   409→				termExplain = new JSONArray();
   410→				explain.put(new JSONObject().put(AND, termExplain));
   411→			}
   412→			BoolQueryBuilder subQuery = QueryBuilders.boolQuery();
   413→			Iterator<String> termIter = extAttr.iterator();
   414→			for (; termIter.hasNext();) {
   415→				String term = termIter.next();
   416→				String type = typeAttr.type();
   417→				if (highlightTerms != null) {
   418→					highlightTerms.add(term);
   419→				}
   420→				synonyms = synAttr.getSynonyms();
   421→				if (synonyms == null || synonyms.size() == 0) {
   422→					subQuery.must().add(QueryBuilders.multiMatchQuery(term, fields).fields(boostMap).analyzer(analyzer));
   423→					if (explain != null) {
   424→						termExplain.put(term);
   425→					}
   426→				} else {
   427→					/**
   428→					 * 확장어의 동의어가 존재할때
   429→					 */
   430→					JSONArray subExplain = new JSONArray();
   431→					subExplain.put(term);
   432→					termExplain.put(new JSONObject().put(OR, subExplain));
   433→					MultiMatchQueryBuilder termQuery = QueryBuilders.multiMatchQuery(term, fields);
   434→					subQuery.must().add(synonymQuery(termQuery, synonyms, fields, boostMap, termAttr, typeAttr, synAttr, extAttr, highlightTerms, subExplain,analyzer));
   435→				}
   436→				logger.trace("a-term:{} / type:{} / synonoym:{}", term, type, synonyms);
   437→			}
   438→			BoolQueryBuilder parent = QueryBuilders.boolQuery();
   439→			parent.should().add(query);
   440→			parent.should().add(subQuery);
   441→			ret = parent;
   442→		}
   443→		return ret;
   444→	}
   445→
   446→	/**
   447→	 * 확장어 질의 문자열 객체 생성
   448→	 */
   449→	public final static JSONObject extraJSONQuery(JSONObject query, String[] fields,
   450→		CharTermAttribute termAttr, TypeAttribute typeAttr, SynonymAttribute synAttr, 
   451→		ExtraTermAttribute extAttr, String analyzer) {
   452→		List<CharSequence> synonyms = null;
   453→		JSONObject ret = query;
   454→		if (extAttr != null && extAttr.size() > 0) {
   455→			JSONObject subQuery = new JSONObject();
   456→			Iterator<String> termIter = extAttr.iterator();
   457→			for (; termIter.hasNext();) {
   458→				String term = termIter.next();
   459→				String type = typeAttr.type();
   460→				synonyms = synAttr.getSynonyms();
   461→				JSONObject termQuery = new JSONObject();
   462→				termQuery.put(MULTIMATCH, 
   463→					new JSONObject().put(ANALYZER, analyzer)
   464→						.put(QUERY, term)
   465→						.put(FIELDS, fields)
   466→					);
   467→
   468→				if (synonyms == null || synonyms.size() == 0) {
   469→					appendJSONQuery(subQuery, MUST, termQuery);
   470→				} else {
   471→					/**
   472→					 * 확장어의 동의어가 존재할때
   473→					 */
   474→					appendJSONQuery(subQuery, MUST, synonymJSONQuery(termQuery, synonyms, fields, termAttr, typeAttr, synAttr, extAttr, analyzer));
   475→				}
   476→				logger.trace("a-term:{} / type:{} / synonoym:{}", term, type, synonyms);
   477→			}
   478→			JSONObject parent = new JSONObject();
   479→			appendJSONQuery(parent, SHOULD, subQuery);
   480→			appendJSONQuery(parent, SHOULD, query);
   481→			ret = parent;
   482→		}
   483→		return ret;
   484→	}
   485→
   486→	/**
   487→	 * AND 조건 불리언 질의객체 생성
   488→	 */
   489→	public static QueryBuilder andQuery(QueryBuilder... queries) {
   490→		BoolQueryBuilder ret = QueryBuilders.boolQuery();
   491→		for (QueryBuilder query : queries) {
   492→			ret.must(query);
   493→		}
   494→		return ret;
   495→	}
   496→
   497→	/**
   498→	 * OR 조건 불리언 질의객체 생성
   499→	 */
   500→	public static QueryBuilder orQuery(QueryBuilder... queries) {
   501→		BoolQueryBuilder ret = QueryBuilders.boolQuery();
   502→		for (QueryBuilder query : queries) {
   503→			ret.should(query);
   504→		}
   505→		return ret;
   506→	}
   507→}

